import { OrgChart, type OrgChartNode, type OrgChartNodeSelectDetail } from '@absoluteui/components/org-chart';

const nodes: OrgChartNode[] = [
  { id: 'ceo', parentId: null, label: 'Ada Lovelace', title: 'Chief Executive Officer' },
  { id: 'cto', parentId: 'ceo', label: 'Grace Hopper', title: 'Chief Technology Officer' },
  { id: 'cfo', parentId: 'ceo', label: 'Mary Jackson', title: 'Chief Financial Officer' },
  { id: 'eng', parentId: 'cto', label: 'Margaret Hamilton', title: 'Engineering Lead', description: 'Boston' },
];

const host = document.createElement('div');
document.body.append(host);
const chart = OrgChart.create(host, { label: 'Company structure', nodes });
host.addEventListener('aui-node-select', (event) => {
  const { node } = (event as CustomEvent<OrgChartNodeSelectDetail>).detail;
  host.dataset.selected = node.label;
});
chart.fit();

import { OrgChart, type OrgChartLoadErrorDetail, type OrgChartNode } from '@absoluteui/components/org-chart';
import { TextInput } from '@absoluteui/components/text-input';

const top: OrgChartNode[] = [
  { id: 'ceo', parentId: null, label: 'Ada Lovelace', title: 'CEO' },
  { id: 'sales', parentId: 'ceo', label: 'Sales', title: 'Division', hasChildren: true },
  { id: 'ops', parentId: 'ceo', label: 'Operations', title: 'Division', hasChildren: true },
];

const host = document.querySelector<HTMLElement>('#org');
if (host) {
  const chart = OrgChart.create(host, {
    label: 'Organization',
    nodes: top,
    orientation: 'horizontal',
    requestTimeoutMs: 10_000,
    loadChildren: async (node, signal) => {
      const response = await fetch(`/api/people?manager=${encodeURIComponent(node.id)}`, { signal });
      if (!response.ok) throw new Error(`Team request failed: ${String(response.status)}`);
      return (await response.json()) as OrgChartNode[];
    },
  });
  host.addEventListener('aui-load-error', (event) => {
    host.dataset.failed = (event as CustomEvent<OrgChartLoadErrorDetail>).detail.id;
  });
  const searchHost = document.createElement('div');
  const search = TextInput.create(searchHost, { label: 'Find a person', hideLabel: true, type: 'search' }).input;
  search.addEventListener('change', () => {
    const first = chart.search(search.value)[0];
    if (first) chart.reveal(first, { select: true });
  });
  host.before(searchHost);
}

import { OrgChart, type OrgChartNode, type OrgChartNodeMoveDetail } from '@absoluteui/components/org-chart';
import { Button } from '@absoluteui/components/button';

let saved: OrgChartNode[] = [
  { id: 'lead', parentId: null, label: 'Team Lead', locked: true },
  { id: 'a', parentId: 'lead', label: 'Alex Kim', title: 'Designer' },
  { id: 'b', parentId: 'lead', label: 'Sam Lee', title: 'Developer' },
  { id: 'c', parentId: 'b', label: 'Robin Park', title: 'Intern' },
];

const host = document.createElement('div');
document.body.append(host);
const chart = OrgChart.create(host, {
  label: 'Team',
  nodes: saved,
  editable: true,
  // Interns stay with developers.
  canMove: (node, parent) => node.title !== 'Intern' || parent?.title === 'Developer',
});
host.addEventListener('aui-node-move', (event) => {
  saved = (event as CustomEvent<OrgChartNodeMoveDetail>).detail.nodes;
});
const undo = document.createElement('button');
undo.type = 'button';
undo.textContent = 'Undo last move';
Button.enhance(undo);
undo.addEventListener('click', () => {
  chart.undo();
});
host.after(undo);

import { OrgChart } from '@absoluteui/components/org-chart';
import { downloadOrgChart } from '@absoluteui/components/org-chart-export';
import { Button } from '@absoluteui/components/button';

const host = document.createElement('div');
document.body.append(host);
const chart = OrgChart.create(host, {
  label: 'Board',
  nodes: [
    { id: 'chair', parentId: null, label: 'Chair', title: 'Jordan Blake' },
    { id: 'audit', parentId: 'chair', label: 'Audit committee', title: '3 members' },
  ],
  nodeWidth: 240,
  nodeHeight: 64,
  // Non-interactive content only: the card is part of the treeitem.
  renderNode: (node, { doc, childCount }) => {
    const box = doc.createElement('span');
    const name = doc.createElement('strong');
    name.textContent = node.label;
    const meta = doc.createElement('span');
    meta.textContent = `, ${node.title ?? ''}${childCount > 0 ? `, ${String(childCount)} reports` : ''}`;
    box.append(name, meta);
    return box;
  },
});
const save = document.createElement('button');
save.type = 'button';
save.textContent = 'Download PNG';
Button.enhance(save);
save.addEventListener('click', () => {
  void downloadOrgChart(chart, { format: 'png', fileName: 'board' });
});
host.after(save);

import { layoutOrgChart } from '@absoluteui/components/org-chart';

const layout = layoutOrgChart(
  [{ id: 'a', children: [{ id: 'b', children: [] }, { id: 'c', children: [] }] }],
  { nodeWidth: 120, nodeHeight: 40, siblingGap: 16, levelGap: 32, orientation: 'vertical' },
);
const root = layout.boxes.get('a');
document.body.dataset.size = `${String(layout.width)}x${String(layout.height)} root at ${String(root?.x ?? 0)}`;
